            javascript() {
                return function (){
                    const $el = this.$el;
                    if(!$el) return;
                    let link = this.settings.link_redirect,
                    form_action_after_submit = this.settings.form_action_after_submit || 'default',
                    hidePopup = this.settings.hide_popup_when_success || false;
                    // id_wheelspin = this.settings.id_wheelspin || '';
                    let files = $el.querySelector('.ecom-contact-form-file[type="file"]');
                    const rootId = this.id;
                    const popup_container = this.settings.popup_container || null;
                    function ecomContactRedirect(){
                        if(link && link.href) {
                            let href = link.href;
                            if(href=='') return false;
                            let target = link.target;

                            if(target === '_blank'){
                                window.open(href);
                            }
                            else{
                                window.location.href = href;
                            }
                        }
                    }
                    //
                    const form = $el.querySelector('#ecom-contact-form-' + rootId);
                    if(!form) return;
                    const submitBtn = form.querySelector('.ecom__form-button'),
                        successMessage = form.querySelector('.ecom__form-success'),
                        message = form.querySelector('.ecom__form-message'),
                        errorMessage = form.querySelector('.ecom__form-status');
                    if(!submitBtn) return;

                    // ===== GA4 tracking (gtag.js / GTM embedded in theme) =====
                    // Empty event name disables tracking entirely.
                    const ga4EventName = this.isLive === true ? this.settings.ga4_event_name : '';
                    const ga4FormName = this.settings.tracking_id || 'contact_form';
                    const ga4Send = function (name, extra) {
                        if (!ga4EventName) return;
                        const payload = Object.assign({
                            form_id: form.id,
                            form_name: ga4FormName,
                            form_destination: 'ecomposer_contact'
                        }, extra || {});
                        if (typeof window.gtag === 'function') {
                            window.gtag('event', name, payload);
                        }
                        if (window.dataLayer && typeof window.dataLayer.push === 'function') {
                            window.dataLayer.push(Object.assign({ event: name }, payload));
                        }
                    };
                    form.addEventListener('submit', function () {
                        ga4Send('form_submit');
                    });

                    // Must stay above the ajax handler below: it calls stopImmediatePropagation(),
                    // which would prevent any submit listener registered after it from running.
                    if(form.dataset.ecTrackingId)
                    {
                        form.addEventListener('submit', function(){
                            if(window.Shopify && window.Shopify.analytics)
                            {
                                Shopify.analytics.publish("ec_custom_events",{
                                    "button_id": form.id,
                                    "tracking_id": form.dataset.ecTrackingId
                                })
                            }
                        },{once: true});
                    }

                    form.addEventListener('submit', function(event) {
                        event.preventDefault();
                        event.stopImmediatePropagation();
                        submitBtn.classList.add('ecom-ajax-loading', 'ecom-loading');
                        const formData = new FormData(form),
                            domain = window.location.origin,
                            proxy_path = window.EComposer && window.EComposer.proxy_path;
                        const campaign = formData.get('contact[campaign]');
                        if (!campaign) {
                            const layout_id = window.EComposer?.PAGE?.layout_id || window.EComposer?.TEMPLATE?.layout_id;
                            formData.set('contact[campaign]', layout_id);
                        }
                        const url = `${domain}${proxy_path}/ecom-contact`;
                        fetch(url, {
                            method: 'POST',
                            body: formData
                        })
                        .then(response => response.json())
                        .then(data => {
                            if(data.status === 'success') {
                                // Fire before the switch: 'redirect' navigates away and 'popup' can return early.
                                ga4Send(ga4EventName, { method: 'contact_form' });
                                switch(form_action_after_submit) {
                                    case 'spin':
                                        const wheelspin = document.querySelector('.ecom__wheel-spin');
                                        if(wheelspin) {
                                            const spin = wheelspin.querySelector('.ecom-wheel-spin-wrapper');
                                            if(spin) {
                                                spin.dispatchEvent(new CustomEvent('ecom-wheel-spin:init'+spin.dataset.id));
                                            }
                                        }
                                        break;
                                    case 'popup':
                                    const popupDataElement = document.querySelector('#ecom-popup-data');
                                        if (!popupDataElement) {
                                            console.warn('Ecom popup data element not found');
                                            return;
                                        }
                                        const dataPopupContainer = JSON.parse(popupDataElement.innerHTML);
                                        if (dataPopupContainer && popup_container && popup_container.id) {
                                            const popupItem = dataPopupContainer.find(item => item.id === popup_container.id);
                                            if(popupItem && window.EComPopup.popupContainerHandler) {
                                                window.EComPopup.popupContainerHandler(popupItem);
                                                if(hidePopup) {
                                                    let classPopupTemplate = 'ecom-popup-container-template-html-' + popupItem.id;
                                                    let COOKIE_NAME = popupItem.id + '+' + popupItem.settings?.popup_version;
                                                    window.EComPopup.setCookie(COOKIE_NAME, classPopupTemplate, {
                                                        maxAgeSeconds: 9999999999,
                                                        path: "/",
                                                        sameSite: "Lax",
                                                    });
                                                }
                                            }
                                        }
                                        break;
                                    case 'redirect':
                                        ecomContactRedirect();
                                        break;
                                }
                                successMessage.style.display = 'block';
                                message.style.display = 'none';
                            }
                            else {
                                if(message && errorMessage) {
                                    const errorMissingEmail = errorMessage.dataset.errorMissingEmail,
                                    errorEmailAlready = errorMessage.dataset.errorEmailAlready,
                                    errorEmailNotValid = errorMessage.dataset.errorEmailNotValid;
                                    
                                    switch(data.type) {
                                        case 'invalid_email': 
                                            errorMessage.innerText = errorEmailNotValid
                                            break;
                                        case 'alredy_email': 
                                            errorMessage.innerText = errorEmailAlready
                                            break;
                                        case 'missing_email': 
                                            errorMessage.innerText = errorMissingEmail
                                            break;
                                        case 'contact_no_access':
                                        case 'contact_limit_reached':
                                            errorMessage.innerText = data.message || errorEmailNotValid;
                                            break;
                                        default:
                                            errorMessage.innerText = data.message || errorEmailNotValid
                                            break;
                                    }
                                    successMessage.style.display = 'none';
                                    message.style.display = 'block';
                                }
                            }
                        })
                        .catch(error => console.error(error))
                        .finally(function() {
                            submitBtn.classList.remove('ecom-ajax-loading', 'ecom-loading');
                        })
                    })
                    if(files){
                        // handler upload file to store
                        form.setAttribute('enctype', "multipart/form-data");
                        form.addEventListener('submit', function(event) {
                            if(!files.value || files.value === '') return;
                            event.preventDefault();
                            event.stopImmediatePropagation();
                            submitBtn.classList.add('ecom-ajax-loading', 'ecom-loading');
                            const inputFile = form.querySelector('input[type="file"]');
                            let formData = new FormData(),
                                domain = window.location.origin,
                                proxy_path = window.EComposer && window.EComposer.proxy_path;
                            const url = `${domain}${proxy_path}/contact-form`;
                            formData.append('file', inputFile.files[0])
                            if(inputFile.value && proxy_path) {
                                //'https://ecomposer-quangtiep.myshopify.com/apps/ecomposer-tiep/contact-form' url test
                                fetch(url, {
                                    method: 'POST',
                                    body: formData
                                })
                                .then(response => response.json())
                                .then(data => {
                                    if(data.status === 'success') {
                                        let name = inputFile.name;
                                        inputFile.remove();
                                        let file = document.createElement('input');
                                        file.value = data.src_file;
                                        file.type = 'hidden';
                                        file.name = name;
                                        form.appendChild(file);
                                        form.submit();
                                    }
                                    else {
                                        alert(`Notice: ${data.message}`);
                                    }
                                })
                                .catch(error => console.error(error))
                                .finally(function() {
                                    submitBtn.classList.remove('ecom-ajax-loading', 'ecom-loading');
                                })
                            }

                        })

                        // let label = files.nextElementSibling,
                        //     labelVal = label.querySelector('span').innerHTML;
                        files.addEventListener('change', function(){
                            const maxSizeInBytes = 10 * 1024 * 1024; // 10 MB (adjust as needed)
                            if (this.files[0].size > maxSizeInBytes) {
                              this.value = '';
                              alert("File size exceeds the maximum allowed limit (10MB).");
                            }
                            // if (this.files[0].name.endsWith('.html')) {
                            //   this.value = '';
                            //   alert('Not supported for uploading HTML files');
                            // }
                            return;
                            // let fileName = '';
                            // if(this.files && this.files.length > 1){
                            //     fileName = this.dataset.multipleCaption || '';
                            //     fileName = fileName.replace('{count}', this.files.length)
                            // }
                            // else fileName = e.target.value.split('\\').pop();
                            // if(fileName){
                            //     label.querySelector('span').innerHTML = fileName;
                            // }
                            // else {
                            //     label.querySelector('span').innerHTML = labelVal;
                            // }
                        });
					}
                    //Check if there is any check box type and required
                    let requiredCheckBoxList = $el.querySelectorAll('.ecom-required--checkbox');

                    submitBtn.addEventListener('click', function(e) {
                        if(requiredCheckBoxList.length > 0) {
                            requiredCheckBoxList.forEach(function(checkboxGroup) {
                                let checkbox_items = checkboxGroup.querySelectorAll('input[type=checkbox]');
                                if(checkbox_items.length == 0) return;
                                let isChecked = false;

                                checkbox_items.forEach(function(checkbox) {
                                    if(checkbox.checked) {
                                        isChecked = true;
                                    }
                                })

                                if(isChecked) {
                                    checkbox_items.forEach(function(checkbox) {
                                        checkbox.required = false;
                                    })
                                } else {
                                    checkbox_items.forEach(function(checkbox) {
                                        checkbox.required = true;
                                    })
                                }
                            })
                        }


                    })

                }
            },
            isFullWidth () {
                return this.data?.settings?.fields &&
                    this.data.settings?.fields.every(field => field?.settings?.width === '100%');
            },
